public static class SkillSpriteChecks {
 public static void Run(){int n=0;Action<bool,string> c=(ok,text)=>{if(!ok)throw new Exception(text);n++;};var character=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>("Assets/Shioka/調整Data/Fighter/Awari/Data/AwariCharacter.asset");var source=AssetDatabase.LoadAssetAtPath<TrainingMoveData>("Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP/Data.asset");string bytes=File.ReadAllText(AssetDatabase.GetAssetPath(source));string path="Assets/__SkillSprites_"+Guid.NewGuid().ToString("N")+".asset";TrainingMoveDataEditor editor=null;GameObject host=null;TrainingMoveSet set=null;try{var target=UnityEngine.Object.Instantiate(source);target.data.spriteSequence=new TrainingSpriteSequence();AssetDatabase.CreateAsset(target,path);editor=(TrainingMoveDataEditor)Editor.CreateEditor(target);var draft=editor.Draft;draft.data.spriteSequence=new TrainingSpriteSequence{frames=new[]{new TrainingSpriteFrame{sprite=character.IdleSprite,holdFrames=2},new TrainingSpriteFrame{sprite=character.ForwardSprite,holdFrames=3}}};var seq=draft.data.spriteSequence;c(seq.Sample(0)==character.IdleSprite,"frame0");c(seq.Sample(1.5f)==character.IdleSprite,"fractional frame retains half-open interval");c(seq.Sample(1.99f)==character.IdleSprite,"before boundary");c(seq.Sample(2)==character.ForwardSprite,"exact hold boundary");c(seq.Sample(4.9f)==character.ForwardSprite,"last interval");c(seq.Sample(200)==character.ForwardSprite,"short sequence holds final sprite");c(seq.Sample(float.NaN)==null,"invalid clock fallback");var first=seq.frames[0];seq.frames[0]=seq.frames[1];seq.frames[1]=first;c(seq.Sample(0)==character.ForwardSprite&&seq.Sample(3)==character.IdleSprite,"reorder keeps per-image holds");first=seq.frames[0];seq.frames[0]=seq.frames[1];seq.frames[1]=first;c(target.data.spriteSequence.frames.Length==0,"draft never mutates source before save");editor.ReloadDraft();c(editor.Draft.data.spriteSequence.frames.Length==0,"Cancel reload discards sequence edits");editor.Draft.data.spriteSequence=seq;float total=target.data.Duration;TrainingMoveDataEditor.SaveDraft(target,editor.Draft);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);target=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(path);c(target.data.spriteSequence.frames.Length==2&&target.data.spriteSequence.frames[1].sprite==character.ForwardSprite,"same skill save/reload preserves sprites");c(target.hideFlags==HideFlags.None,"source persistence flags unchanged");c(target.data.Duration==total&&target.data.startupFrames==source.data.startupFrames&&target.data.activeFrames==source.data.activeFrames&&target.data.recoveryFrames==source.data.recoveryFrames,"image duration never rescales move phases");var test=UnityEngine.Object.Instantiate(target);test.data.spriteSequence.frames[0].holdFrames=0;c(!test.data.spriteSequence.Validate(out _),"zero hold invalid");try{TrainingMoveDataEditor.SaveDraft(target,test);throw new Exception("Invalid save accepted");}catch(ArgumentException){n++;}test.data.spriteSequence.frames[0].holdFrames=-1;c(!test.data.spriteSequence.Validate(out _),"negative hold invalid");test.data.spriteSequence.frames[0].holdFrames=40000;c(!test.data.spriteSequence.Validate(out _),"bounded hold");test.data.spriteSequence.frames[0].holdFrames=1;test.data.spriteSequence.frames[0].sprite=null;c(!test.data.spriteSequence.Validate(out _),"missing sprite invalid");test.data.spriteSequence.frames=new TrainingSpriteFrame[0];c(test.data.spriteSequence.Validate(out _)&&test.data.spriteSequence.Sample(0)==null,"empty sequence valid legacy fallback");UnityEngine.Object.DestroyImmediate(test);
 set=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<TrainingMoveSet>("Assets/Shioka/調整Data/Fighter/Awari/Skill/Moves.asset"));foreach(var r in set.catalog)if(r.asset==source)r.asset=target;set.OnAfterDeserialize();host=new GameObject("Skill sprite preview QA");host.hideFlags=HideFlags.HideAndDontSave;var spatial=host.AddComponent<TrainingSpatialAuthoring>();spatial.moves=set;spatial.character=character;spatial.hurtboxes=AssetDatabase.LoadAssetAtPath<TrainingHurtboxProfile>("Assets/Shioka/調整Data/Fighter/Awari/Hurtboxes.asset");spatial.command=TrainingCommand.Light;spatial.Reload();spatial.frame=2;spatial.Refresh();c(spatial.preview.sprite==character.ForwardSprite,"spatial preview shares sequence clock during startup");spatial.facing=-1;spatial.Refresh();c(spatial.preview.flipX,"spatial preview mirrors left");spatial.frame=source.data.Duration*60;spatial.Refresh();Debug.Log("SPRITE_ENDPOINT frame="+spatial.frame.ToString("R")+" end="+(spatial.Move.Duration*60).ToString("R")+" actual="+spatial.preview.sprite.name+" expected="+character.IdleSprite.name+" sample="+(spatial.Move.SequenceSpriteAt(spatial.frame)==null?"null":"sequence"));c(spatial.preview.sprite==character.IdleSprite,"spatial scrub action endpoint returns legacy presentation");c(target.data.SequenceSpriteAt(target.data.Duration*60)==null,"sequence cannot extend move endpoint");c(target.data.SequenceSpriteAt(2)==character.ForwardSprite,"move wrapper preserves integer hold selection");c(target.data.SequenceSpriteAt(target.data.Duration*60-.01f)==character.ForwardSprite,"fractional recovery before endpoint remains visible");c(File.ReadAllText(AssetDatabase.GetAssetPath(source))==bytes,"adopted weakP data never changed");Debug.Log("SKILL_SPRITES "+n+" passed");var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-spriteEditReport");if(i>=0)File.WriteAllText(args[i+1],n+" PASS; 0 FAIL; editor save/cancel/preview");}finally{if(editor!=null)UnityEngine.Object.DestroyImmediate(editor);if(host!=null)UnityEngine.Object.DestroyImmediate(host);if(set!=null)UnityEngine.Object.DestroyImmediate(set);AssetDatabase.DeleteAsset(path);}}
}


public static class AuthoringDraftEditabilityChecks {
 static System.Collections.Generic.List<string> rows;static int count;
 const string Skill="Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP/Data.asset",Motion="Assets/Shioka/調整Data/Fighter/Awari/Move/ForwardWalk/ForwardWalk.asset";
 static void C(bool ok,string message){rows.Add((ok?"PASS ":"FAIL ")+message);if(!ok)throw new Exception(message);count++;}
 static TrainingMotionAction MotionDraft(Editor editor)=>(TrainingMotionAction)typeof(TrainingMotionActionEditor).GetField("draft",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(editor);
 static void ReloadMotion(Editor editor)=>typeof(TrainingMotionActionEditor).GetMethod("Reload",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(editor,null);
