  skill=Editor.CreateEditor(AssetDatabase.LoadAssetAtPath<TrainingMoveData>(Skill));motion=Editor.CreateEditor(AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(Motion));
  var a=new SerializedObject(((TrainingMoveDataEditor)skill).Draft);var b=new SerializedObject(MotionDraft(motion));
  C(!a.FindProperty("data.startupFrames").editable,"baseline startup field is not editable");C(!a.FindProperty("data.spriteSequence.frames.Array.data[0].holdFrames").editable,"baseline skill hold field is not editable");C(!b.FindProperty("poses.Array.data[0].holdFrames").editable,"baseline motion hold field is not editable");C((((TrainingMoveDataEditor)skill).Draft.hideFlags&HideFlags.NotEditable)!=0,"baseline draft has NotEditable flag");Report();
 }finally{if(skill!=null)UnityEngine.Object.DestroyImmediate(skill);if(motion!=null)UnityEngine.Object.DestroyImmediate(motion);}}
 public static void Run(){rows=new System.Collections.Generic.List<string>();count=0;string skillBytes=File.ReadAllText(Skill),motionBytes=File.ReadAllText(Motion);string prefix="Assets/__DraftEditability_"+Guid.NewGuid().ToString("N");string skillPath=prefix+"_Skill.asset",motionPath=prefix+"_Motion.asset";TrainingMoveDataEditor skillEditor=null;TrainingMotionActionEditor motionEditor=null;
 try{
  var skill=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<TrainingMoveData>(Skill));AssetDatabase.CreateAsset(skill,skillPath);var motion=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(Motion));AssetDatabase.CreateAsset(motion,motionPath);skillEditor=(TrainingMoveDataEditor)Editor.CreateEditor(skill);motionEditor=(TrainingMotionActionEditor)Editor.CreateEditor(motion);
  var draft=skillEditor.Draft;C((draft.hideFlags&HideFlags.NotEditable)==0,"skill draft omits only edit prohibition");C((draft.hideFlags&HideFlags.DontSave)==HideFlags.DontSave,"skill draft remains nonpersistent");var so=new SerializedObject(draft);
  foreach(var name in new[]{"startupFrames","activeFrames","recoveryFrames"})C(so.FindProperty("data."+name).editable,name+" editable by Inspector property");C(so.FindProperty("data.spriteSequence.frames.Array.data[0].holdFrames").editable,"skill per-image hold editable");
  string before=File.ReadAllText(skillPath);float startup=skill.data.startupFrames,active=skill.data.activeFrames,recovery=skill.data.recoveryFrames;int hold=skill.data.spriteSequence.frames[0].holdFrames;
  so.FindProperty("data.startupFrames").floatValue=startup+1;so.FindProperty("data.activeFrames").floatValue=active+1;so.FindProperty("data.recoveryFrames").floatValue=recovery+1;so.FindProperty("data.spriteSequence.frames.Array.data[0].holdFrames").intValue=hold+1;so.ApplyModifiedProperties();
  C(skill.data.startupFrames==startup&&skill.data.activeFrames==active&&skill.data.recoveryFrames==recovery&&skill.data.spriteSequence.frames[0].holdFrames==hold,"Inspector edits touch draft only");C(File.ReadAllText(skillPath)==before,"draft edit never writes skill asset");
  skillEditor.ReloadDraft();C(skillEditor.Draft.data.startupFrames==startup&&skillEditor.Draft.data.activeFrames==active&&skillEditor.Draft.data.recoveryFrames==recovery&&skillEditor.Draft.data.spriteSequence.frames[0].holdFrames==hold,"Cancel reload restores timings and holds");C(File.ReadAllText(skillPath)==before,"Cancel leaves saved bytes unchanged");
  so=new SerializedObject(skillEditor.Draft);so.FindProperty("data.startupFrames").floatValue=startup+1;so.FindProperty("data.activeFrames").floatValue=active+1;so.FindProperty("data.recoveryFrames").floatValue=recovery+1;so.FindProperty("data.spriteSequence.frames.Array.data[0].holdFrames").intValue=hold+1;so.ApplyModifiedProperties();TrainingMoveDataEditor.SaveDraft(skill,skillEditor.Draft);AssetDatabase.ImportAsset(skillPath,ImportAssetOptions.ForceUpdate);skill=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(skillPath);
  C(Mathf.Approximately(skill.data.startupFrames,startup+1)&&Mathf.Approximately(skill.data.activeFrames,active+1)&&Mathf.Approximately(skill.data.recoveryFrames,recovery+1),"Save persists all three phase timings");C(skill.data.spriteSequence.frames[0].holdFrames==hold+1,"Save persists skill hold");C(skill.hideFlags==HideFlags.None,"skill source retains ordinary persistence flags");
  UnityEngine.Object.DestroyImmediate(skillEditor);skillEditor=(TrainingMoveDataEditor)Editor.CreateEditor(skill);C(skillEditor.Draft.data.spriteSequence.frames[0].holdFrames==hold+1,"reselect reloads saved skill");skillEditor.Draft.data.startupFrames=999;UnityEngine.Object.DestroyImmediate(skillEditor);skillEditor=(TrainingMoveDataEditor)Editor.CreateEditor(skill);C(Mathf.Approximately(skillEditor.Draft.data.startupFrames,startup+1),"selection change discards unsaved skill draft");
  var md=MotionDraft(motionEditor);C((md.hideFlags&HideFlags.NotEditable)==0,"motion draft omits edit prohibition");C((md.hideFlags&HideFlags.DontSave)==HideFlags.DontSave,"motion draft remains nonpersistent");var ms=new SerializedObject(md);C(ms.FindProperty("poses.Array.data[0].holdFrames").editable&&ms.FindProperty("poses.Array.data[0].visualOffset").editable,"motion image holds and offsets editable");string mb=File.ReadAllText(motionPath);int mh=motion.poses[0].holdFrames;ms.FindProperty("poses.Array.data[0].holdFrames").intValue=mh+1;ms.ApplyModifiedProperties();C(motion.poses[0].holdFrames==mh&&File.ReadAllText(motionPath)==mb,"motion Inspector edits draft only");ReloadMotion(motionEditor);C(MotionDraft(motionEditor).poses[0].holdFrames==mh&&File.ReadAllText(motionPath)==mb,"motion Cancel preserves saved bytes");MotionDraft(motionEditor).poses[0].holdFrames=mh+1;TrainingMotionActionEditor.SaveDraft(motion,MotionDraft(motionEditor));AssetDatabase.ImportAsset(motionPath,ImportAssetOptions.ForceUpdate);motion=AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(motionPath);C(motion.poses[0].holdFrames==mh+1,"motion Save persists hold");C(motion.hideFlags==HideFlags.None,"motion source retains ordinary persistence flags");
  UnityEngine.Object.DestroyImmediate(motionEditor);motionEditor=(TrainingMotionActionEditor)Editor.CreateEditor(motion);MotionDraft(motionEditor).poses[0].holdFrames=999;UnityEngine.Object.DestroyImmediate(motionEditor);motionEditor=(TrainingMotionActionEditor)Editor.CreateEditor(motion);C(MotionDraft(motionEditor).poses[0].holdFrames==mh+1,"selection change discards unsaved motion draft");
  C(File.ReadAllText(Skill)==skillBytes&&File.ReadAllText(Motion)==motionBytes,"canonical 5LP and ForwardWalk asset bytes unchanged");Report();SkillSpriteChecks.Run();SkillSpriteFolderChecks.Run();
 }finally{if(skillEditor!=null)UnityEngine.Object.DestroyImmediate(skillEditor);if(motionEditor!=null)UnityEngine.Object.DestroyImmediate(motionEditor);AssetDatabase.DeleteAsset(skillPath);AssetDatabase.DeleteAsset(motionPath);if(File.ReadAllText(Skill)!=skillBytes||File.ReadAllText(Motion)!=motionBytes)throw new Exception("Canonical source mutated");}}
}


[InitializeOnLoad]public static class AuthoringDraftPlayGuardChecks {
 const string Pending="ShiokaDraftPlayGuard";
 static AuthoringDraftPlayGuardChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Fresh Edit session required");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(TrainingFlowSession.TitleScene);SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Tick(){if(!EditorApplication.isPlaying||Time.frameCount<3)return;SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;TrainingMoveData skill=null;TrainingMotionAction motion=null;int exit=0;var rows=new System.Collections.Generic.List<string>();try{
  const string sp="Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP/Data.asset",mp="Assets/Shioka/調整Data/Fighter/Awari/Move/ForwardWalk/ForwardWalk.asset";string sb=File.ReadAllText(sp),mb=File.ReadAllText(mp);var sourceSkill=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(sp);var sourceMotion=AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(mp);skill=UnityEngine.Object.Instantiate(sourceSkill);motion=UnityEngine.Object.Instantiate(sourceMotion);
  bool refused=false;try{TrainingMoveDataEditor.SaveDraft(sourceSkill,skill);}catch(InvalidOperationException){refused=true;}if(!refused)throw new Exception("Skill save accepted during Play");rows.Add("PASS Play refuses skill authoring save");
  refused=false;try{TrainingMotionActionEditor.SaveDraft(sourceMotion,motion);}catch(InvalidOperationException){refused=true;}if(!refused)throw new Exception("Motion save accepted during Play");rows.Add("PASS Play refuses motion authoring save");if(File.ReadAllText(sp)!=sb||File.ReadAllText(mp)!=mb)throw new Exception("Saved authoring bytes changed");rows.Add("PASS source asset bytes unchanged during Play");rows.Add("3 PASS; actual Editor Play save guards");
 }catch(Exception e){exit=1;rows.Add("FAIL "+e);Debug.LogException(e);}finally{if(skill!=null)UnityEngine.Object.DestroyImmediate(skill);if(motion!=null)UnityEngine.Object.DestroyImmediate(motion);var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-draftPlayReport");if(i>=0)File.WriteAllLines(args[i+1],rows);EditorApplication.Exit(exit);}}
}
